#include "../include/bonsai_kg_v4.hpp"
#include "../include/bonsai_kg_v4_io.hpp"
#include "../cuda/kag_adapter_v4.cuh"
#include "../../cuda-engine/include/runtime.cuh"
#include "v4_synthetic_io.hpp"
#include <cuda_runtime.h>
#include <cstdlib>
#include <iostream>
#include <stdexcept>
#include <vector>
using namespace bonsaikg4;using namespace kagcuda;
struct DeviceOwner4{Node4*n=nullptr;uint16_t*c=nullptr;BbDecl4*bb=nullptr;ValueRef4*v=nullptr;FeatureArgRef4*a=nullptr;Predicate4*q=nullptr;Lifecycle4*l=nullptr;Effect4*e=nullptr;~DeviceOwner4(){if(n)cudaFree(n);if(c)cudaFree(c);if(bb)cudaFree(bb);if(v)cudaFree(v);if(a)cudaFree(a);if(q)cudaFree(q);if(l)cudaFree(l);if(e)cudaFree(e);}};
template<class T>static T*cp(const std::vector<T>&x){if(x.empty())return nullptr;T*d=nullptr;KAGCUDA_CHECK(cudaMalloc((void**)&d,x.size()*sizeof(T)));KAGCUDA_CHECK(cudaMemcpy(d,x.data(),x.size()*sizeof(T),cudaMemcpyHostToDevice));return d;}
struct TickOut4{uint8_t status=0,pad=0;uint16_t fault=0;ActionResult4 action{};};struct Final4{int step=0,done=0;double r0=0,r1=0;};
__global__ void init4(Config cfg,DeviceTables tables,PolicyView4 p,Sim*sim,int32_t*bb,NodeState4*ns,RuntimeMeta4*meta){if(blockIdx.x||threadIdx.x)return;sim->init(cfg,&tables);RuntimeView4 st{bb,ns,meta};reset_runtime(p,st);}
__global__ void step4(PolicyView4 p,Sim*sim,int32_t*bb,NodeState4*ns,RuntimeMeta4*meta,TickOut4*out,int32_t*bbhist,NodeState4*nshist,int seat){if(blockIdx.x||threadIdx.x||sim->st.done)return;RuntimeView4 st{bb,ns,meta};CudaObservation4 obs(make_observation(*sim,seat));ActionResult4 ar{};Status r=tick4(p,st,obs,sim->cfg.max_orders,ar,nullptr);int t=sim->st.step;out[t].status=(uint8_t)r;out[t].fault=meta->fault;out[t].action=ar;for(uint16_t i=0;i<p.n_bb;++i)bbhist[(size_t)t*p.n_bb+i]=bb[i];for(uint16_t i=0;i<p.n_state;++i)nshist[(size_t)t*p.n_state+i]=ns[i];Action a0{},a1{};a0.n_units=sim->st.farms[0].n_units;a1.n_units=sim->st.farms[1].n_units;if(seat==0)to_cuda_action4(ar,a0);else to_cuda_action4(ar,a1);sim->step_with_unit_counts(a0,sim->st.farms[0].n_units,a1,sim->st.farms[1].n_units);}
__global__ void final4(const Sim*sim,Final4*out){if(blockIdx.x||threadIdx.x)return;out->step=sim->st.step;out->done=sim->st.done;out->r0=sim->st.farms[0].money;out->r1=sim->st.farms[1].money;}
int main(int argc,char**argv){try{if(argc<2||argc>5)throw std::runtime_error("usage: v4_cuda_game_runner POLICY [SEED] [STEPS] [SEAT]");const uint64_t seed=argc>=3?std::strtoull(argv[2],nullptr,10):12345ull;const int steps=argc>=4?std::atoi(argv[3]):16;const int seat=argc>=5?std::atoi(argv[4]):0;if(seat<0||seat>1)throw std::runtime_error("seat must be 0/1");auto owned=load_compiled4(argv[1]);PolicyView4 hp=owned.view();DeviceOwner4 d;d.n=cp(owned.nodes);d.c=cp(owned.child_refs);d.bb=cp(owned.bb);d.v=cp(owned.values);d.a=cp(owned.feature_args);d.q=cp(owned.predicates);d.l=cp(owned.lifecycles);d.e=cp(owned.effects);PolicyView4 p=hp;p.nodes=d.n;p.child_refs=d.c;p.bb=d.bb;p.values=d.v;p.feature_args=d.a;p.predicates=d.q;p.lifecycles=d.l;p.effects=d.e;configure_device();TablesOwner tables;Config cfg;cfg.seed=seed;cfg.episode_steps=steps;Sim*sim=nullptr;int32_t*bb=nullptr,*bh=nullptr;NodeState4*ns=nullptr,*nh=nullptr;RuntimeMeta4*meta=nullptr;TickOut4*out=nullptr;Final4*fin=nullptr;KAGCUDA_CHECK(cudaMalloc((void**)&sim,sizeof(Sim)));if(hp.n_bb){KAGCUDA_CHECK(cudaMalloc((void**)&bb,hp.n_bb*sizeof(int32_t)));KAGCUDA_CHECK(cudaMalloc((void**)&bh,(size_t)steps*hp.n_bb*sizeof(int32_t)));}if(hp.n_state){KAGCUDA_CHECK(cudaMalloc((void**)&ns,hp.n_state*sizeof(NodeState4)));KAGCUDA_CHECK(cudaMalloc((void**)&nh,(size_t)steps*hp.n_state*sizeof(NodeState4)));}KAGCUDA_CHECK(cudaMalloc((void**)&meta,sizeof(RuntimeMeta4)));KAGCUDA_CHECK(cudaMalloc((void**)&out,(size_t)steps*sizeof(TickOut4)));KAGCUDA_CHECK(cudaMalloc((void**)&fin,sizeof(Final4)));KAGCUDA_CHECK(cudaMemset(out,0,(size_t)steps*sizeof(TickOut4)));init4<<<1,1>>>(cfg,tables.dev,p,sim,bb,ns,meta);KAGCUDA_CHECK(cudaDeviceSynchronize());for(int i=0;i<steps-1;++i){step4<<<1,1>>>(p,sim,bb,ns,meta,out,bh,nh,seat);KAGCUDA_CHECK(cudaGetLastError());KAGCUDA_CHECK(cudaDeviceSynchronize());}final4<<<1,1>>>(sim,fin);KAGCUDA_CHECK(cudaDeviceSynchronize());Final4 hf{};KAGCUDA_CHECK(cudaMemcpy(&hf,fin,sizeof(hf),cudaMemcpyDeviceToHost));std::vector<TickOut4>ho(hf.step);KAGCUDA_CHECK(cudaMemcpy(ho.data(),out,ho.size()*sizeof(TickOut4),cudaMemcpyDeviceToHost));std::vector<int32_t>hbb((size_t)hf.step*hp.n_bb);std::vector<NodeState4>hns((size_t)hf.step*hp.n_state);if(!hbb.empty())KAGCUDA_CHECK(cudaMemcpy(hbb.data(),bh,hbb.size()*sizeof(int32_t),cudaMemcpyDeviceToHost));if(!hns.empty())KAGCUDA_CHECK(cudaMemcpy(hns.data(),nh,hns.size()*sizeof(NodeState4),cudaMemcpyDeviceToHost));for(int t=0;t<hf.step;++t){RuntimeMeta4 m{ho[t].fault,0,0};RuntimeView4 st{hp.n_bb?hbb.data()+(size_t)t*hp.n_bb:nullptr,hp.n_state?hns.data()+(size_t)t*hp.n_state:nullptr,&m};bonsaikg4_test::print_snapshot(std::cout,0,t,(Status)ho[t].status,st,ho[t].action,hp.n_bb,hp.n_state);}std::cerr<<"FINAL ticks="<<hf.step<<" done="<<hf.done<<" seat="<<seat<<" reward0="<<hf.r0<<" reward1="<<hf.r1<<"\n";cudaFree(sim);if(bb)cudaFree(bb);if(bh)cudaFree(bh);if(ns)cudaFree(ns);if(nh)cudaFree(nh);cudaFree(meta);cudaFree(out);cudaFree(fin);return 0;}catch(const std::exception&e){std::cerr<<"ERROR: "<<e.what()<<'\n';return 2;}}
